match srv {
  Ok(fd) => {
    let cli = tcp_connect("127.0.0.1:47312")
    match cli {
      Ok(cfd) => {
        let acc = tcp_accept(fd)
        match acc {
          Ok(afd) => {
            tcp_close(cfd)
            let mut tries = 0
            let mut failed = false
            while tries < 200 && failed == false {
              let s = tcp_send(afd, "xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx")
              match s {
                Ok(n) => { tries = tries + 1 },
                Err(r) => { failed = true }
              }
            }
            print("peer gone, send refused: {failed}")
            tcp_close(afd)
          },
          Err(r) => { print("accept {r}") }
        }
      },
      Err(r) => { print("connect {r}") }
    }
    tcp_close(fd)
  },
  Err(r) => { print("listen {r}") }
}

