fn div(a, b) {
  return a / b
}

fn rem(a, b) {
  return a % b
}

fn has(a, b) {
  return a in b
}

fn at(a, i) {
  return a[i]
}

fn main() -> i64 {
  let inf = 1e308 * 10.0
  try { print(div(1.5, "")) } catch e { print(e) }
  try { print(div("", 0)) } catch e { print(e) }
  try { print(div(1, 0)) } catch e { print(e) }
  try { print(div([1], 2.5)) } catch e { print(e) }
  try { print(rem("", 0)) } catch e { print(e) }
  try { print(rem(5, 0)) } catch e { print(e) }
  try { print(rem(inf, 1)) } catch e { print(e) }
  try { print(rem(-7.5, 2)) } catch e { print(e) }
  try { print(has(0, "abc")) } catch e { print(e) }
  try { print(has("b", "abc")) } catch e { print(e) }
  try { print(has([], {})) } catch e { print(e) }
  try { print(has("a", {"a": 1})) } catch e { print(e) }
  try { print(has(2, [1, 2])) } catch e { print(e) }
  try { print(at({}, [])) } catch e { print(e) }
  try { print(at({"a": 1}, [1, 2])) } catch e { print(e) }
  return 0
}
